export function bindFittedFascia(material){material.onBeforeCompile=shader=>{
shader.vertexShader="varying vec3 vFasciaPosition;\n"+shader.vertexShader;
shader.vertexShader=shader.vertexShader.replace("#include <begin_vertex>","#include <begin_vertex>\n vFasciaPosition=transformed;");
shader.fragmentShader="varying vec3 vFasciaPosition;\nvec3 fittedFasciaNormal(vec3 p){float h=p.y-0.82;float dx=(-0.0817854479)*p.x+(0.3636371493)*p.x*h+(-0.4164301753)*p.x*h*h+(-1.8674051762)*p.x*p.x*p.x;float dy=0.0131210592+(-2.7789192200)*h+(-21.3106541634)*h*h+(0.1818185747)*p.x*p.x+(-0.4164301753)*p.x*p.x*h;return normalize(vec3(-dx,-dy,1.0));}\n"+shader.fragmentShader;
shader.fragmentShader=shader.fragmentShader.replace("#include <normal_fragment_maps>","#include <normal_fragment_maps>\n normal=normalize(mat3(viewMatrix)*fittedFasciaNormal(vFasciaPosition));");
shader.fragmentShader=shader.fragmentShader.replace("#include <clearcoat_normal_fragment_begin>","#ifdef USE_CLEARCOAT\n vec3 clearcoatNormal=normal;\n #endif");
};material.customProgramCacheKey=()=>"fascia-fit-v16";material.needsUpdate=true;}
